/* ShiftWise Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

/* === CSS RESET === */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

/* === CSS VARIABLES === */
:root {
  /* Colors - OKLCH based */
  --color-primary: oklch(25% 0.15 265);
  --color-primary-blue: oklch(50% 0.18 265);
  --color-accent: oklch(70% 0.18 35);
  --color-accent-hover: oklch(65% 0.22 35);
  --color-success: oklch(65% 0.18 145);
  --color-error: oklch(60% 0.20 25);

  /* Hex approximations for use */
  --color-primary-hex: #1a2744;
  --color-primary-blue-hex: #3b5bdb;
  --color-accent-hex: #f97316;
  --color-accent-hover-hex: #ea6516;
  --color-success-hex: #22c55e;
  --color-error-hex: #dc2626;
  --color-surface-hex: #fafbfc;
  --color-text-hex: #1e293b;
  --color-text-secondary-hex: #64748b;
  --color-border-hex: #e2e8f0;

  /* Typography */
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Layout */
  --max-width: 1280px;
  --border-radius-sm: 6px;
  --border-radius: 8px;
  --border-radius-lg: 12px;
  --border-radius-xl: 16px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-md: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition: 300ms ease;
  --transition-slow: 500ms ease;
}

/* === BASE STYLES === */
body {
  font-family: var(--font-family);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text-hex);
  background-color: white;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

/* === TYPOGRAPHY === */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-text-hex);
}

h1 {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 600;
}

h4 {
  font-size: 1.25rem;
  font-weight: 600;
}

p {
  color: var(--color-text-secondary-hex);
}

.text-sm {
  font-size: 0.875rem;
}

.text-lg {
  font-size: 1.125rem;
}

.text-xl {
  font-size: 1.25rem;
}

.text-center {
  text-align: center;
}

.text-white {
  color: white;
}

.text-accent {
  color: var(--color-accent-hex);
}

.font-semibold {
  font-weight: 600;
}

.font-bold {
  font-weight: 700;
}

/* === LAYOUT === */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.section {
  padding: var(--space-20) 0;
}

.section-sm {
  padding: var(--space-12) 0;
}

.section-lg {
  padding: var(--space-24) 0;
}

.section-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto var(--space-12);
}

.section-header p {
  margin-top: var(--space-4);
  font-size: 1.125rem;
}

.grid {
  display: grid;
  gap: var(--space-6);
}

.grid-2 {
  grid-template-columns: repeat(2, 1fr);
}

.grid-3 {
  grid-template-columns: repeat(3, 1fr);
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

.flex {
  display: flex;
}

.flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.flex-col {
  flex-direction: column;
}

.gap-2 {
  gap: var(--space-2);
}

.gap-4 {
  gap: var(--space-4);
}

.gap-6 {
  gap: var(--space-6);
}

.gap-8 {
  gap: var(--space-8);
}

/* === BUTTONS === */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-family: var(--font-family);
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--border-radius);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-decoration: none;
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primary {
  background-color: var(--color-accent-hex);
  color: white;
  border-color: var(--color-accent-hex);
}

.btn-primary:hover {
  background-color: var(--color-accent-hover-hex);
  border-color: var(--color-accent-hover-hex);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary-hex);
  border-color: var(--color-primary-hex);
}

.btn-secondary:hover {
  background-color: var(--color-primary-hex);
  color: white;
}

.btn-white {
  background-color: white;
  color: var(--color-primary-hex);
  border-color: white;
}

.btn-white:hover {
  background-color: var(--color-surface-hex);
  border-color: var(--color-surface-hex);
}

.btn-lg {
  padding: var(--space-4) var(--space-8);
  font-size: 1.125rem;
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: 0.875rem;
}

/* === CARDS === */
.card {
  background: white;
  border-radius: var(--border-radius-lg);
  padding: var(--space-6);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-hex);
  transition: all var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--color-primary-blue-hex), var(--color-primary-hex));
  border-radius: var(--border-radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-4);
}

.card-icon svg {
  width: 28px;
  height: 28px;
  color: white;
}

/* === HEADER === */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-primary-hex);
  padding: var(--space-4) 0;
  transition: all var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 1.5rem;
  font-weight: 800;
  color: white;
  text-decoration: none;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-accent-hex);
  border-radius: var(--border-radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 800;
  font-size: 1.25rem;
}

.nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-6);
}

.nav-link {
  color: rgba(255, 255, 255, 0.85);
  font-weight: 500;
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: white;
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

/* Mobile Menu Button */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--space-2);
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: white;
  margin: 6px 0;
  transition: all var(--transition);
}

.mobile-menu-btn.active span:nth-child(1) {
  transform: rotate(45deg) translate(6px, 6px);
}

.mobile-menu-btn.active span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-btn.active span:nth-child(3) {
  transform: rotate(-45deg) translate(6px, -6px);
}

/* Mobile Navigation */
.mobile-nav {
  display: none;
  position: fixed;
  top: 64px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-primary-hex);
  padding: var(--space-6);
  transform: translateX(100%);
  transition: transform var(--transition);
  z-index: 999;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.mobile-nav-link {
  color: white;
  font-size: 1.25rem;
  font-weight: 500;
  padding: var(--space-3) 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.mobile-nav-cta {
  margin-top: var(--space-6);
}

/* === HERO === */
.hero {
  padding-top: calc(64px + var(--space-16));
  padding-bottom: var(--space-16);
  background: linear-gradient(135deg, var(--color-primary-hex) 0%, #2d3a5c 100%);
  color: white;
  text-align: center;
}

.hero-content {
  max-width: 900px;
  margin: 0 auto;
}

.hero h1 {
  color: white;
  margin-bottom: var(--space-6);
}

.hero-subtitle {
  font-size: 1.25rem;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: var(--space-8);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.hero-buttons {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
}

.hero-small {
  padding-top: calc(64px + var(--space-12));
  padding-bottom: var(--space-12);
}

/* === FEATURES GRID === */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.feature-card {
  text-align: center;
}

.feature-card h4 {
  margin-bottom: var(--space-3);
}

.feature-card p {
  font-size: 0.9375rem;
}

/* === HOW IT WORKS === */
.how-it-works {
  background: var(--color-surface-hex);
}

.steps {
  display: flex;
  gap: var(--space-8);
  justify-content: center;
  flex-wrap: wrap;
}

.step {
  flex: 1;
  min-width: 250px;
  max-width: 280px;
  text-align: center;
  position: relative;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--color-accent-hex);
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  margin: 0 auto var(--space-4);
}

.step h4 {
  margin-bottom: var(--space-2);
}

.step p {
  font-size: 0.9375rem;
}

/* === TESTIMONIALS === */
.testimonials-wrapper {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform var(--transition);
}

.testimonial {
  min-width: 100%;
  padding: 0 var(--space-4);
}

.testimonial-card {
  background: white;
  border-radius: var(--border-radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  text-align: center;
  border: 1px solid var(--color-border-hex);
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--color-text-hex);
  margin-bottom: var(--space-6);
  line-height: 1.7;
}

.testimonial-quote::before {
  content: '"';
  font-size: 3rem;
  color: var(--color-accent-hex);
  line-height: 0;
  display: block;
  margin-bottom: var(--space-4);
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-text-hex);
}

.testimonial-role {
  color: var(--color-text-secondary-hex);
  font-size: 0.875rem;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-6);
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--color-border-hex);
  background: white;
  cursor: pointer;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
}

.testimonial-nav button:hover {
  border-color: var(--color-primary-hex);
  background: var(--color-primary-hex);
  color: white;
}

.testimonial-nav button svg {
  width: 20px;
  height: 20px;
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--color-border-hex);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.dot.active {
  background: var(--color-primary-hex);
  transform: scale(1.2);
}

/* === STATS === */
.stats-section {
  background: var(--color-primary-hex);
  padding: var(--space-16) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
}

.stat {
  text-align: center;
  color: white;
}

.stat-value {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 800;
  color: var(--color-accent-hex);
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-label {
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.85);
}

/* === PRICING TEASER === */
.pricing-teaser {
  background: var(--color-surface-hex);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: white;
  border-radius: var(--border-radius-xl);
  padding: var(--space-8);
  text-align: center;
  border: 2px solid transparent;
  transition: all var(--transition);
}

.pricing-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--color-accent-hex);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent-hex);
  color: white;
  padding: var(--space-1) var(--space-4);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card h4 {
  font-size: 1.25rem;
  margin-bottom: var(--space-4);
}

.pricing-price {
  margin-bottom: var(--space-4);
}

.pricing-price .amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-text-hex);
}

.pricing-price .period {
  color: var(--color-text-secondary-hex);
}

.pricing-features {
  text-align: left;
  margin-bottom: var(--space-6);
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) 0;
  font-size: 0.9375rem;
  color: var(--color-text-secondary-hex);
}

.pricing-features li svg {
  width: 20px;
  height: 20px;
  color: var(--color-success-hex);
  flex-shrink: 0;
}

.pricing-features li.disabled {
  color: var(--color-text-secondary-hex);
  opacity: 0.5;
}

.pricing-features li.disabled svg {
  color: var(--color-text-secondary-hex);
}

/* === CTA SECTION === */
.cta-section {
  background: linear-gradient(135deg, var(--color-accent-hex) 0%, var(--color-accent-hover-hex) 100%);
  padding: var(--space-20) 0;
  text-align: center;
  color: white;
}

.cta-section h2 {
  color: white;
  margin-bottom: var(--space-4);
}

.cta-section p {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1.25rem;
  margin-bottom: var(--space-8);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-section .btn-white {
  font-size: 1.125rem;
  padding: var(--space-4) var(--space-10);
}

/* === FOOTER === */
.footer {
  background: var(--color-primary-hex);
  color: white;
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer-brand .logo {
  margin-bottom: var(--space-4);
}

.footer-brand p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9375rem;
  max-width: 300px;
}

.footer-column h5 {
  color: white;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-4);
}

.footer-column ul li {
  margin-bottom: var(--space-2);
}

.footer-column a {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9375rem;
  transition: color var(--transition-fast);
}

.footer-column a:hover {
  color: white;
}

.footer-bottom {
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-bottom p {
  color: rgba(255, 255, 255, 0.5);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  color: rgba(255, 255, 255, 0.5);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: white;
}

/* === FEATURE DETAIL SECTIONS === */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.feature-detail.reverse {
  direction: rtl;
}

.feature-detail.reverse > * {
  direction: ltr;
}

.feature-content h3 {
  margin-bottom: var(--space-4);
}

.feature-content p {
  margin-bottom: var(--space-6);
}

.feature-list {
  margin-bottom: var(--space-6);
}

.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  color: var(--color-text-secondary-hex);
}

.feature-list li svg {
  width: 20px;
  height: 20px;
  color: var(--color-success-hex);
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-visual {
  background: linear-gradient(135deg, var(--color-surface-hex), #e2e8f0);
  border-radius: var(--border-radius-xl);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-border-hex);
}

.feature-visual-inner {
  width: 80%;
  height: 80%;
  background: white;
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary-hex);
  font-size: 1.25rem;
  font-weight: 600;
}

/* === INTEGRATIONS GRID === */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

.integration-category {
  background: white;
  border-radius: var(--border-radius-lg);
  padding: var(--space-6);
  text-align: center;
  border: 1px solid var(--color-border-hex);
  transition: all var(--transition);
}

.integration-category:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.integration-category h5 {
  margin-bottom: var(--space-3);
}

.integration-category p {
  font-size: 0.875rem;
}

/* === PRICING TABLE PAGE === */
.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-10);
}

.toggle-switch {
  position: relative;
