  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.feature-card {
  text-align: center;
}

.feature-card h4 {
  margin-bottom: var(--space-3);
}

.feature-card p {
  font-size: 0.9375rem;
}

/* === HOW IT WORKS === */
.how-it-works {
  background: var(--color-surface-hex);
}

.steps {
  display: flex;
  gap: var(--space-8);
  justify-content: center;
  flex-wrap: wrap;
}

.step {
  flex: 1;
  min-width: 250px;
  max-width: 280px;
  text-align: center;
  position: relative;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--color-accent-hex);
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  margin: 0 auto var(--space-4);
}

.step h4 {
  margin-bottom: var(--space-2);
}

.step p {
  font-size: 0.9375rem;
}

/* === TESTIMONIALS === */
.testimonials-wrapper {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform var(--transition);
}

.testimonial {
  min-width: 100%;
  padding: 0 var(--space-4);
}

.testimonial-card {
  background: white;
  border-radius: var(--border-radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  text-align: center;
  border: 1px solid var(--color-border-hex);
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--color-text-hex);
  margin-bottom: var(--space-6);
  line-height: 1.7;
}

.testimonial-quote::before {
  content: '"';
  font-size: 3rem;
  color: var(--color-accent-hex);
  line-height: 0;
  display: block;
  margin-bottom: var(--space-4);
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-text-hex);
}

.testimonial-role {
  color: var(--color-text-secondary-hex);
  font-size: 0.875rem;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-6);
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--color-border-hex);
  background: white;
  cursor: pointer;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
}

.testimonial-nav button:hover {
  border-color: var(--color-primary-hex);
  background: var(--color-primary-hex);
  color: white;
}

.testimonial-nav button svg {
  width: 20px;
  height: 20px;
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--color-border-hex);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.dot.active {
  background: var(--color-primary-hex);
  transform: scale(1.2);
}

/* === STATS === */
.stats-section {
  background: var(--color-primary-hex);
  padding: var(--space-16) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
}

.stat {
  text-align: center;
  color: white;
}

.stat-value {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 800;
  color: var(--color-accent-hex);
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-label {
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.85);
}

/* === PRICING TEASER === */
.pricing-teaser {
  background: var(--color-surface-hex);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: white;
  border-radius: var(--border-radius-xl);
  padding: var(--space-8);
  text-align: center;
  border: 2px solid transparent;
  transition: all var(--transition);
}

.pricing-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--color-accent-hex);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent-hex);
  color: white;
  padding: var(--space-1) var(--space-4);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card h4 {
  font-size: 1.25rem;
  margin-bottom: var(--space-4);
}

.pricing-price {
  margin-bottom: var(--space-4);
}

.pricing-price .amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-text-hex);
}

.pricing-price .period {
  color: var(--color-text-secondary-hex);
}

.pricing-features {
  text-align: left;
  margin-bottom: var(--space-6);
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) 0;
  font-size: 0.9375rem;
  color: var(--color-text-secondary-hex);
}

.pricing-features li svg {
  width: 20px;
  height: 20px;
  color: var(--color-success-hex);
  flex-shrink: 0;
}

.pricing-features li.disabled {
  color: var(--color-text-secondary-hex);
  opacity: 0.5;
}

.pricing-features li.disabled svg {
  color: var(--color-text-secondary-hex);
}

/* === CTA SECTION === */
.cta-section {
  background: linear-gradient(135deg, var(--color-accent-hex) 0%, var(--color-accent-hover-hex) 100%);
  padding: var(--space-20) 0;
  text-align: center;
  color: white;
}

.cta-section h2 {
  color: white;
  margin-bottom: var(--space-4);
}

.cta-section p {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1.25rem;
  margin-bottom: var(--space-8);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-section .btn-white {
  font-size: 1.125rem;
  padding: var(--space-4) var(--space-10);
}

/* === FOOTER === */
.footer {
  background: var(--color-primary-hex);
  color: white;
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer-brand .logo {
  margin-bottom: var(--space-4);
}

.footer-brand p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9375rem;
  max-width: 300px;
}

.footer-column h5 {
  color: white;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-4);
}

.footer-column ul li {
  margin-bottom: var(--space-2);
}

.footer-column a {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9375rem;
  transition: color var(--transition-fast);
}

.footer-column a:hover {
  color: white;
}

.footer-bottom {
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-bottom p {
  color: rgba(255, 255, 255, 0.5);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  color: rgba(255, 255, 255, 0.5);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: white;
}

/* === FEATURE DETAIL SECTIONS === */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.feature-detail.reverse {
  direction: rtl;
}

.feature-detail.reverse > * {
  direction: ltr;
}

.feature-content h3 {
  margin-bottom: var(--space-4);
}

.feature-content p {
  margin-bottom: var(--space-6);
}

.feature-list {
  margin-bottom: var(--space-6);
}

.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  color: var(--color-text-secondary-hex);
}

.feature-list li svg {
  width: 20px;
  height: 20px;
  color: var(--color-success-hex);
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-visual {
  background: linear-gradient(135deg, var(--color-surface-hex), #e2e8f0);
  border-radius: var(--border-radius-xl);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-border-hex);
}

.feature-visual-inner {
  width: 80%;
  height: 80%;
  background: white;
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary-hex);
  font-size: 1.25rem;
  font-weight: 600;
}

/* === INTEGRATIONS GRID === */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

.integration-category {
  background: white;
  border-radius: var(--border-radius-lg);
  padding: var(--space-6);
  text-align: center;
  border: 1px solid var(--color-border-hex);
  transition: all var(--transition);
}

.integration-category:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.integration-category h5 {
  margin-bottom: var(--space-3);
}

.integration-category p {
  font-size: 0.875rem;
}

/* === PRICING TABLE PAGE === */
.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-10);
}

.toggle-switch {
  position: relative;
  width: 56px;
  height: 30px;
  background: var(--color-border-hex);
  border-radius: 15px;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.toggle-switch.active {
  background: var(--color-accent-hex);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 24px;
  height: 24px;
  background: white;
  border-radius: 50%;
  transition: transform var(--transition-fast);
}

.toggle-switch.active::after {
  transform: translateX(26px);
}

.toggle-label {
  font-weight: 600;
  color: var(--color-text-secondary-hex);
}

.toggle-label.active {
  color: var(--color-text-hex);
}

.save-badge {
  background: var(--color-success-hex);
  color: white;
  padding: var(--space-1) var(--space-3);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
}

.full-pricing-table {
  max-width: 1000px;
  margin: 0 auto;
  background: white;
  border-radius: var(--border-radius-xl);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--color-border-hex);
}

.pricing-table-header {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  background: var(--color-primary-hex);
  color: white;
  padding: var(--space-4) var(--space-6);
}

.pricing-table-header span {
  text-align: center;
  font-weight: 600;
}

.pricing-table-header span:first-child {
  text-align: left;
}

.pricing-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--color-border-hex);
  align-items: center;
}

.pricing-row:last-child {
  border-bottom: none;
}

.pricing-row:hover {
  background: var(--color-surface-hex);
}

.pricing-row .feature-name {
  color: var(--color-text-hex);
  font-weight: 500;
}

.pricing-row span {
  text-align: center;
  color: var(--color-text-secondary-hex);
}

.pricing-row span.yes {
  color: var(--color-success-hex);
}

.pricing-row span.no {
  color: var(--color-text-secondary-hex);
  opacity: 0.5;
}

/* === FAQ === */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-border-hex);
}

.faq-question {
  width: 100%;
  padding: var(--space-5) 0;
  background: none;
  border: none;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  text-align: left;
  font-family: var(--font-family);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text-hex);
}

.faq-question:hover {
  color: var(--color-primary-blue-hex);
}

.faq-question svg {
  width: 24px;
  height: 24px;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition), padding var(--transition);
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: var(--space-5);
}

.faq-answer p {
  color: var(--color-text-secondary-hex);
  line-height: 1.7;
}

/* === ABOUT PAGE === */
.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
}

.team-member {
  text-align: center;
}

.team-avatar {
  width: 120px;
  height: 120px;
  background: linear-gradient(135deg, var(--color-primary-blue-hex), var(--color-primary-hex));
  border-radius: 50%;
  margin: 0 auto var(--space-4);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 2rem;
  font-weight: 700;
}

.team-member h4 {
  margin-bottom: var(--space-1);
}

.team-member p {
  font-size: 0.875rem;
}

.mission-section {
  background: var(--color-surface-hex);
}

.mission-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.mission-content h2 {
  margin-bottom: var(--space-6);
}

.mission-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

/* === CONTACT PAGE === */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: start;
}

.contact-form {
  background: white;
  border-radius: var(--border-radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border-hex);
}

.form-group {
  margin-bottom: var(--space-5);
}

.form-group label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--space-2);
  color: var(--color-text-hex);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  font-family: var(--font-family);
  font-size: 1rem;
  border: 2px solid var(--color-border-hex);
  border-radius: var(--border-radius);
  transition: all var(--transition-fast);
  background: white;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--color-primary-blue-hex);
  box-shadow: 0 0 0 3px rgba(59, 91, 219, 0.1);
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-group.error input,
.form-group.error select,
.form-group.error textarea {
  border-color: var(--color-error-hex);
}

.form-error {
  color: var(--color-error-hex);
  font-size: 0.875rem;
  margin-top: var(--space-2);
  display: none;
}

.form-group.error .form-error {
  display: block;
}

.form-success {
  background: var(--color-success-hex);
  color: white;
  padding: var(--space-4);
  border-radius: var(--border-radius);
  text-align: center;
  font-weight: 600;
  display: none;
}

.form-success.show {
  display: block;
}

.offices {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.office-card {
  background: white;
  border-radius: var(--border-radius-lg);
  padding: var(--space-6);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-hex);
}

.office-card h4 {
  margin-bottom: var(--space-2);
  color: var(--color-primary-hex);
}

.office-card p {
  font-size: 0.9375rem;
}

.contact-info {
  margin-top: var(--space-8);
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  color: var(--color-text-secondary-hex);
}

.contact-info-item svg {
  width: 20px;
  height: 20px;
  color: var(--color-accent-hex);
}

/* === RESPONSIVE === */
@media (max-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--space-8);
  }

  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards .pricing-card:last-child {
    grid-column: span 2;
    max-width: 50%;
    margin: 0 auto;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .feature-detail {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .feature-detail.reverse {
    direction: ltr;
  }

  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .team-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-table-header,
  .pricing-row {
    grid-template-columns: 1.5fr 1fr 1fr 1fr;
  }

  .contact-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-cta {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .mobile-nav {
    display: block;
  }

  .hero {
    padding-top: calc(64px + var(--space-12));
  }

  .section {
    padding: var(--space-12) 0;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--space-6);
  }

  .stat-value {
    font-size: 2rem;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .pricing-cards .pricing-card:last-child {
    grid-column: span 1;
    max-width: 100%;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .pricing-table-header,
  .pricing-row {
    grid-template-columns: 1.2fr 1fr 1fr 1fr;
    padding: var(--space-3);
    font-size: 0.875rem;
  }

  .pricing-table-header span:first-child,
  .pricing-row .feature-name {
    font-size: 0.8rem;
  }

  .team-grid {
    grid-template-columns: 1fr;
  }

  .steps {
    flex-direction: column;
    align-items: center;
  }

  .step {
    max-width: 100%;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-4);
  }

  .hero-buttons {
    flex-direction: column;
  }

  .hero-buttons .btn {
    width: 100%;
  }

  .integrations-grid {
    grid-template-columns: 1fr;
  }

  .pricing-toggle {
    flex-direction: column;
    gap: var(--space-2);
  }

  .pricing-table-header,
  .pricing-row {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .pricing-row .feature-name {
    grid-column: span 3;
    text-align: left;
    padding-bottom: var(--space-2);
    border-bottom: 1px dashed var(--color-border-hex);
    margin-bottom: var(--space-2);
  }

  .testimonial-card {
    padding: var(--space-6);
  }
}
