@media (max-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--space-8);
  }

  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards .pricing-card:last-child {
    grid-column: span 2;
    max-width: 50%;
    margin: 0 auto;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .feature-detail {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .feature-detail.reverse {
    direction: ltr;
  }

  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .team-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-table-header,
  .pricing-row {
    grid-template-columns: 1.5fr 1fr 1fr 1fr;
  }

  .contact-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-cta {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .mobile-nav {
    display: block;
  }

  .hero {
    padding-top: calc(64px + var(--space-12));
  }

  .section {
    padding: var(--space-12) 0;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--space-6);
  }

  .stat-value {
    font-size: 2rem;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .pricing-cards .pricing-card:last-child {
    grid-column: span 1;
    max-width: 100%;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .pricing-table-header,
  .pricing-row {
    grid-template-columns: 1.2fr 1fr 1fr 1fr;
    padding: var(--space-3);
    font-size: 0.875rem;
  }

  .pricing-table-header span:first-child,
  .pricing-row .feature-name {
    font-size: 0.8rem;
  }

  .team-grid {
    grid-template-columns: 1fr;
  }

  .steps {
    flex-direction: column;
    align-items: center;
  }

  .step {
    max-width: 100%;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-4);
  }

  .hero-buttons {
    flex-direction: column;
  }

  .hero-buttons .btn {
    width: 100%;
  }

  .integrations-grid {
    grid-template-columns: 1fr;
  }

  .pricing-toggle {
    flex-direction: column;
    gap: var(--space-2);
  }

  .pricing-table-header,
