    grid-column: span 3;
    text-align: left;
    padding-bottom: var(--space-2);
    border-bottom: 1px dashed var(--color-border-hex);
    margin-bottom: var(--space-2);
  }

  .testimonial-card {
    padding: var(--space-6);
  }
}

